import re
from datetime import date
from decimal import Decimal

_QTY = re.compile(r"[0-9]+")
_PRICE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
_DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _check(fields):
    if len(fields) != 4:
        return "expected 4 fields, got %d" % len(fields), None
    name, qty, price, day = fields
    if not name:
        return "name is empty", None
    if not _QTY.fullmatch(qty) or int(qty) < 1:
        return "qty must be a positive integer", None
    if not _PRICE.fullmatch(price):
        return "price must be a non-negative amount with at most 2 decimals", None
    parsed = None
    if _DATE.fullmatch(day):
        try:
            parsed = date.fromisoformat(day)
        except ValueError:
            pass
    if parsed is None:
        return "date is not a valid ISO date", None
    return None, {"name": name, "qty": int(qty), "price": Decimal(price), "date": parsed}


def validate(rows):
    valid, errors = [], []
    seen = {}
    for row in rows:
        line = row["line"]
        error, data = _check(row["fields"])
        if error is None:
            key = (data["name"].casefold(), data["date"])
            if key in seen:
                error = "duplicate of line %d" % seen[key]
            else:
                seen[key] = line
        if error is None:
            valid.append({"line": line, **data})
        else:
            errors.append({"line": line, "error": error})
    return valid, errors
