from decimal import Decimal


def summarize(valid, errors):
    total = sum((r["price"] * r["qty"] for r in valid), Decimal(0))
    out = [
        "rows: %d valid, %d invalid" % (len(valid), len(errors)),
        "total: %s" % total.quantize(Decimal("0.01")),
    ]
    out += ["line %d: %s" % (e["line"], e["error"]) for e in errors]
    latest = max((r["date"] for r in valid), default=None)
    out.append("latest: %s" % (latest.isoformat() if latest else "-"))
    return out
